+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+
+import java.util.List;
+
+/**
+ * UC-002: View Veterinarians.
+ *
+ * Route {@code /vets}: a grid of the clinic's veterinarians with their
+ * specialties, loaded as the visitor scrolls (GR-002). The navigation link is
+ * rendered by {@link MainLayout}.
+ */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository vets;
+
+    public VetsView(VetRepository vets) {
+        this.vets = vets;
+
+        setSizeFull();
+
+        Grid<Vet> grid = new Grid<>(Vet.class, false);
+        grid.addColumn(Vet::firstName).setHeader("First Name");
+        grid.addColumn(Vet::lastName).setHeader("Last Name");
+        grid.addColumn(vet -> describe(vet.specialties())).setHeader("Specialties");
+        grid.setDataProvider(DataProvider.fromCallbacks(
+                query -> this.vets.findPage(query.getOffset(), query.getLimit()),
+                query -> this.vets.count()));
+
+        add(grid);
+    }
+
+    private static String describe(List<String> specialties) {
+        return specialties.isEmpty() ? "none" : String.join(", ", specialties);
+    }
+}
